def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                cells.setdefault(grid[r][c], []).append((r, c))

    boxes = {}
    for color, pts in cells.items():
        r0 = min(r for r, c in pts)
        r1 = max(r for r, c in pts)
        c0 = min(c for r, c in pts)
        c1 = max(c for r, c in pts)
        pattern = [
            [grid[r][c] == color for c in range(c0 + 1, c1)]
            for r in range(r0 + 1, r1)
        ]
        boxes[color] = (r0, r1, c0, c1, pattern)

    sources = [color for color, (_, _, _, _, pat) in boxes.items()
               if any(any(row) for row in pat)]
    if not sources:
        return [row[:] for row in grid]

    source = sources[0]
    sr0, sr1, sc0, sc1, pattern = boxes[source]
    sh, sw = sr1 - sr0 + 1, sc1 - sc0 + 1

    out = [[0] * w for _ in range(h)]
    for color, (r0, r1, c0, c1, _) in boxes.items():
        if (r1 - r0 + 1, c1 - c0 + 1) != (sh, sw):
            continue

        for c in range(c0, c1 + 1):
            out[r0][c] = color
            out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = color
            out[r][c1] = color

        if color == source:
            for r, c in cells[color]:
                out[r][c] = color
        else:
            for dr, row in enumerate(pattern, 1):
                for dc, filled in enumerate(row, 1):
                    if filled:
                        out[r0 + dr][c0 + dc] = color

    return out
